    records: list[dict[str, object]] = []
    assert len(templates) == 20
    for tool_idx, (tool_name, calls) in enumerate(templates):
        assert tool_name == MCP_TOOL_SCHEMAS_20[tool_idx]
        assert len(calls) == 8
        for sample_j, payload in enumerate(calls):
            records.append(
                {
                    "id": f"mcp_{tool_idx:02d}_{sample_j}",
                    "category_idx": tool_idx,
                    "category": tool_name,
                    "prompt": payload,
                }
            )
    return records


